# Generated by scripts/render_homebrew.py from verified native release archives.
class ObeyVoice < Formula
  desc "Voice assistant for AI coding with local speech models"
  homepage "https://github.com/Obedience-Corp/obey-voice"

  bottle do
    root_url "https://github.com/Obedience-Corp/homebrew-tap/releases/download/obey-voice-v0.3.0"
    sha256 cellar: :any, arm64_sequoia: "c7521df81808dd814b1567013befe069b45c1ae4d6e6ff1596b5d43e65f3d911"
    sha256 cellar: :any, x86_64_linux:  "b84805f122ee3c2c244d565218f24941943b113a0f34b51cb49269167579b9ad"
  end
  if OS.mac?
    url "https://github.com/Obedience-Corp/obey-voice/releases/download/v0.3.0/obey-voice-v0.3.0-macos-arm64.tar.gz"
    sha256 "2f928b6db81928884d3ad5d67ad7245eaed9a2b13924a13d7c9e5558a9fb7388"
  else
    url "https://github.com/Obedience-Corp/obey-voice/releases/download/v0.3.0/obey-voice-v0.3.0-linux-amd64.tar.gz"
    sha256 "6c0589527044ee36e33b61ba3e3d6d8e18f8fabae987939dc2e01b5f7f05774c"
  end
  license "AGPL-3.0-only"

  pour_bottle? do
    reason "Obey Voice requires glibc 2.39 or newer on Linux (Ubuntu 24.04 or newer)"
    satisfy { !OS.linux? || OS::Linux::Glibc.system_version >= "2.39" }
  end

  on_macos do
    depends_on arch: :arm64
    depends_on macos: :sequoia
  end

  on_linux do
    depends_on arch: :x86_64
  end

  # Avoid stripping the payload; Homebrew still relocates native library IDs.
  skip_clean "libexec"

  def install
    if OS.linux? && OS::Linux::Glibc.system_version < "2.39"
      odie "Obey Voice requires glibc 2.39 or newer on Linux (Ubuntu 24.04 or newer)"
    end

    libexec.install "obey-voice", "lib", "licenses", "LICENSE", "NOTICE"
    # These hashes describe the upstream archive, before Homebrew relocation.
    libexec.install "manifest.json" => "upstream-manifest.json"
    bin.install_symlink libexec/"obey-voice"
    # Keep Homebrew's metafile discovery from moving files out of the manifest.
    prefix.install_symlink libexec/"LICENSE", libexec/"NOTICE"
  end

  def caveats
    <<~EOS
      Run obey-voice to choose providers and set up voice models explicitly.
      Homebrew does not download models, install brain providers, or start services.
      For a compiler-free speech path, select Parakeet STT and Kokoro TTS.
      Native Phonon on Linux requires a separate source toolchain.
      On macOS, grant microphone permission to your terminal when prompted.
      Diagnose audio devices with: obey-voice doctor --voice-devices
      Settings, personas, sessions, and model caches survive upgrades and uninstall.
      Use `type -a obey-voice` to check for installations earlier on your PATH.
    EOS
  end

  test do
    assert_match "version v#{version}", shell_output("#{bin}/obey-voice --version")
    manifest = JSON.parse((libexec/"upstream-manifest.json").read)
    assert_equal "v#{version}", manifest.fetch("version")
    manifest.fetch("files").each do |file|
      assert_path_exists libexec/file.fetch("path")
    end
  end
end
